import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{t}from"./book-open-CtTYPXak.js";import{I as n,L as r,M as i,N as a,O as o,P as s,k as c}from"./shared-BLp3PbbW.js";import{t as l}from"./database-B9dOoFl-.js";import{t as u}from"./route-B96petsN.js";var d=e();function f(){return(0,d.jsxs)(a,{children:[(0,d.jsx)(i,{variant:`project`,chip:`ГЛАВА 4 · КАРТА ОБУЧЕНИЯ`,title:`От FastAPI с JSON к Planner на SQLite`,intro:`Вы уже знакомы с Planner API. В этой главе подготовите приложение к SQLite, постепенно перенесёте чтение и изменения задач на SQL, сохраните прежние данные и проверите, что API и CLI продолжают работать вместе.`,tags:[{icon:(0,d.jsx)(t,{size:14}),label:`4 недели · 20 основных шагов · 37 занятий`},{icon:(0,d.jsx)(l,{size:14}),label:`StudyHub Database API`},{icon:(0,d.jsx)(u,{size:14}),label:`один проект · от API до SQLite`}]}),(0,d.jsxs)(s,{number:`00`,title:`Как устроены учебные недели и номера`,children:[(0,d.jsx)(o,{children:`В главе четыре учебные недели. На каждой рекомендую пройти пять основных занятий: так получается 20 основных шагов с нумерацией от 61 до 80. Дополнительные занятия отмечены точкой, например 68, 68.1 и 68.2. Они помогают глубже разобрать тему основного занятия и не добавляют новый шаг в маршрут. Всего в главе 37 занятий, включая 17 дополнительных.`}),(0,d.jsxs)(r,{children:[(0,d.jsx)(n,{badge:`основной шаг`,title:`Пять основных занятий задают неделю`,children:`Номера с 61 по 65 составляют первую неделю, с 66 по 70 вторую, с 71 по 75 третью и с 76 по 80 четвёртую. Основная нумерация продолжается через всю главу.`}),(0,d.jsx)(n,{badge:`дополнение`,badgeTone:`float`,title:`Точка продолжает тему занятия`,children:`Например, после 68 пройдите 68.1 и 68.2, затем переходите к 69. Дополнения закрепляют отдельные части темы, не меняя нумерацию основных шагов.`}),(0,d.jsx)(n,{badge:`порядок`,badgeTone:`str`,title:`Проходите занятия по порядку`,children:`Рекомендую сначала закончить основное занятие и его продолжения, а потом открывать следующий номер. Один учебный шаг можно спокойно распределить на несколько вечеров.`})]})]}),(0,d.jsxs)(`section`,{className:`rich-section learning-roadmap-preview`,children:[(0,d.jsx)(`div`,{className:`rich-section-title`,children:(0,d.jsx)(`h2`,{children:`Четыре недели от FastAPI к Planner на SQLite`})}),(0,d.jsx)(o,{children:`Сначала укрепите основу FastAPI и разберитесь с устройством базы. Затем переведите Planner на SQL и проверьте, что готовый проект можно надёжно запустить и передать другому человеку.`}),(0,d.jsxs)(r,{children:[(0,d.jsx)(n,{badge:`НЕДЕЛЯ 1`,title:`Подготовьте FastAPI к подключению базы`,children:`Наведёте порядок в структуре приложения, настройках и зависимостях. Разберётесь с заголовками и cookie, чтобы уверенно управлять параметрами запроса и ответа.`}),(0,d.jsx)(n,{badge:`НЕДЕЛЯ 2`,badgeTone:`float`,title:`Поймите, как Planner будет хранить задачи`,children:`От ограничений JSON перейдёте к SQLite, SQL и SQLAlchemy. Подготовите таблицу, запись, чтение и импорт данных, пока привычные API и CLI продолжают работать.`}),(0,d.jsx)(n,{badge:`НЕДЕЛЯ 3`,badgeTone:`str`,title:`Переведите Planner на SQL`,children:`Подключите к базе все операции с задачами, выборки и статистику. Перенесёте старые данные и переключите API и CLI вместе, сохранив прежнее поведение.`}),(0,d.jsx)(n,{badge:`НЕДЕЛЯ 4`,title:`Проверьте готовый проект и его надёжность`,children:`Разберёте ошибки и реальные SQL-запросы, проверите восстановление после сбоя и воспроизведёте запуск проекта по README из чистой копии.`})]})]}),(0,d.jsxs)(s,{number:`01`,title:`Неделя 1 · Подготовьте FastAPI к работе с базой`,children:[(0,d.jsx)(o,{children:`Рекомендую начать с устройства запроса и текущей структуры Planner, затем настроить окружение и подключение сервиса. В конце недели добавите параметры представления через HTTP и cookie. Это подготовит приложение к базе, не затрагивая хранение задач и права доступа.`}),(0,d.jsx)(c,{variant:`connected`,items:[{title:`61 · Пакет ресурса tasks`,description:`Соберёте маршруты и схемы задач в пакет одного ресурса, обновите импорты и проверите знакомые сценарии API и CLI.`},{title:`62 · Настройки окружения`,description:`Вынесете путь к JSON в настройку окружения, проверите значение по умолчанию и исключите локальный .env из Git.`},{title:`62.1 · Общие настройки`,description:`Соберёте настройки в одном месте для API и CLI. Проверите значения и понятную реакцию на ошибочную конфигурацию.`},{title:`63 · Сервис через Depends`,description:`Подключите PlannerService через Depends к маршрутам задач и статистики, сохранив общий сервис и прежнее хранилище.`},{title:`63.1 · Annotated: параметры`,description:`Перепишете объявления Path, Query и Depends в читаемом виде, не меняя ограничения, схемы и ответы API.`},{title:`64 · Зависимости и тесты`,description:`Соберёте параметры выборки и сервис в понятные зависимости. В тесте подмените провайдер и проверите отказ на отдельном JSON-файле.`},{title:`65 · Заголовки и Response`,description:`Добавите GET /preferences с настройкой по умолчанию и проверите входной и ответный HTTP-заголовки, не меняя контракт задач.`},{title:`65.1 · Cookie и вид ответа`,description:`Научите API читать и менять настройку compact или detailed через GET, PUT и DELETE. Проверите повторный запрос с cookie и без неё.`},{title:`65.2 · Безопасность cookie`,description:`Ограничите допустимые значения cookie и настроите её атрибуты. Убедитесь, что выбор представления не выдаёт клиенту никаких прав.`}]}),(0,d.jsxs)(r,{children:[(0,d.jsx)(n,{badge:`структура`,title:`Понятно, где живёт каждый слой`,children:`Разложите маршруты и схемы по пакету ресурса, не перемещая прикладную логику и хранение. Прежние команды останутся на месте.`}),(0,d.jsx)(n,{badge:`настройки`,badgeTone:`float`,title:`API получает готовые зависимости`,children:`Настроите единый источник параметров и подключите сервис через Depends. Это подготовит приложения к общей базе, не создавая второй экземпляр сервиса на каждый запрос.`}),(0,d.jsx)(n,{badge:`HTTP`,badgeTone:`str`,title:`Предпочтение не становится правом доступа`,children:`Добавите headers и cookie для вида представления и проверите границу доверия. Задачи и права пользователя останутся вне этой настройки.`})]})]}),(0,d.jsxs)(s,{number:`02`,title:`Неделя 2 · Подготовьте SQLite-хранилище по шагам`,children:[(0,d.jsx)(o,{children:`Рекомендую двигаться от причины к инструментам: исследовать ограничения JSON, попробовать SQL, а затем собрать Engine, таблицу, Session и SQL-чтение. К концу недели вы подготовите импорт прежних задач. API и CLI пока останутся на привычном JSON, поэтому новую базу можно будет проверить отдельно.`}),(0,d.jsx)(c,{variant:`connected`,items:[{title:`66 · JSON и его пределы`,description:`Проследите, как Planner читает и перезаписывает весь список. На небольшом опыте увидите ограничение такого способа, не рискуя рабочими данными.`},{title:`66.1 · SQLite и основы SQL`,description:`Создадите временную таблицу и выполните параметризованные INSERT и SELECT. Увидите, как база хранит и выбирает отдельные записи.`},{title:`67 · Engine и путь к базе`,description:`Настроите DATABASE_URL и общий Engine. Проверите подключение и убедитесь, что проект находит одну и ту же базу из разных текущих папок.`},{title:`67.1 · Модель ORM и таблица`,description:`Опишете TaskRow и поля таблицы, создадите исходную схему отдельной командой и сверите Python-атрибуты с колонками SQLite.`},{title:`68 · Запись через Session`,description:`Откроете Session, добавите задачу и разберёте flush, commit и refresh. Прочитаете запись новой Session и подтвердите, что она сохранена.`},{title:`68.1 · Транзакция и откат`,description:`Вызовете реальное ограничение, выполните rollback и проверите следующую успешную операцию. Различите отмену изменений и закрытие ресурса.`},{title:`68.2 · Чтение через SELECT`,description:`Прочитаете список и задачу по id через SELECT, обработаете отсутствие записи и преобразуете ORM-объект в знакомую предметную модель.`},{title:`69 · Граница чтения данных`,description:`Добавите JSON-адаптер и переведёте чтение сервиса на операции по смыслу, сохранив прежний файл и поведение Planner.`},{title:`69.1 · Граница записи данных`,description:`Переведёте существующие изменения на новый контракт и уберёте прямые load/save из сервиса, не переписывая CRUD заново.`},{title:`70 · Чтение через SQL-репо`,description:`Реализуете получение списка и задачи из SQLite через SQL-репозиторий. Проверите, что чтение не фиксирует транзакцию записи.`},{title:`70.1 · Ресурс на один запрос`,description:`Ограничите время жизни Session одним HTTP-запросом или CLI-командой и проверите закрытие ресурса при успехе и ошибке.`},{title:`70.2 · Импорт задач в SQLite`,description:`Импортируете копию JSON в пустую тестовую базу одной транзакцией, сохранив id и внутренние поля. Исходный файл останется нетронутым.`}]}),(0,d.jsxs)(r,{children:[(0,d.jsx)(n,{badge:`основа`,title:`Таблица описана и создана явно`,children:`Свяжете Engine, ORM-модель и исходную схему. Сможете показать, где в SQLite находится каждая запись и как она соотносится с объектом Python.`}),(0,d.jsx)(n,{badge:`запись`,badgeTone:`float`,title:`Данные переживают закрытие Session`,children:`Добавите запись в транзакции и прочитаете её новым ресурсом. Разберётесь, когда изменения сохранены, а когда их можно отменить.`}),(0,d.jsx)(n,{badge:`переход`,badgeTone:`str`,title:`SQL-путь готовится без раннего переключения`,children:`Подготовите операции чтения и разовую загрузку старых задач. API и CLI пока продолжают работать через JSON, а переключатся на SQLite вместе позже.`})]})]}),(0,d.jsxs)(s,{number:`03`,title:`Неделя 3 · Переведите Planner на SQL-запросы`,children:[(0,d.jsx)(o,{children:`Когда чтение и ресурсная область уже понятны, рекомендую перенести в SQL операции с задачами, затем фильтры, поиск и статистику. После отдельной проверки API и CLI вместе перенесёте прежние данные и переключите оба интерфейса на SQLite.`}),(0,d.jsx)(c,{variant:`connected`,items:[{title:`71 · Создание и ID из БД`,description:`Подключите создание через SQL-репозиторий и получите id от базы. Перечитайте новую задачу и проверьте, что сервис фиксирует завершённую операцию.`},{title:`71.1 · PUT: замена задачи`,description:`Обновите публичные поля через PUT, сохранив id и внутренние tags. Проверьте найденную и отсутствующую задачу, включая отказ без частичного изменения.`},{title:`72 · PATCH: выбор полей`,description:`Примените только переданные поля: False меняет значение, null и отсутствие поля его сохраняют. Убедитесь, что пустой PATCH не создаёт запись.`},{title:`72.1 · Задача: done и delete`,description:`Подключите done и delete к SQL-хранилищу. Проверьте повторное завершение, ответ DELETE 204 и последующий ответ 404.`},{title:`73 · SQL-фильтр и сводка`,description:`Соберите фильтрацию, порядок и limit в SQL-запросе, а статистику получите агрегатами базы. Сохраните прежнюю форму ответов.`},{title:`73.1 · Поиск в SQL-базе`,description:`Переведите поиск в SQL и сравните результат до и после обновления или импорта. Проверите буквальное совпадение и русский регистр.`},{title:`74 · CLI и ресурс команды`,description:`Подключите SQL-ресурс к обработчикам CLI и открывайте его на одну команду. Проверьте, что длинный интерактивный цикл не удерживает закрытую Session.`},{title:`74.1 · Готовность к переходу`,description:`Проверьте API и CLI на одной тестовой базе, включая импорт и новый id. Закройте пробелы до переключения рабочего приложения.`},{title:`75 · Переход на SQLite`,description:`Остановите записи, перенесите финальное состояние JSON и переключите сборку API и CLI вместе. Повторно проверьте сохранность прежних задач.`},{title:`75.1 · Убираем JSON-backend`,description:`Уберите рабочий JSON-backend, его настройки и fallback. Запустите API и CLI без прежнего файла, сохранив JSON только как формат импорта.`}]}),(0,d.jsxs)(r,{children:[(0,d.jsx)(n,{badge:`операции`,title:`Все действия работают через SQL`,children:`Создание, обновление, завершение и удаление будут обращаться к одной базе. Сервис сохранит прежние правила API и обработку отсутствующих задач.`}),(0,d.jsx)(n,{badge:`запросы`,badgeTone:`float`,title:`База выбирает нужные данные`,children:`Фильтр, сортировка, лимит, поиск и статистика выполняются запросами, а не загрузкой всего списка. Результат останется совместим с привычными ответами.`}),(0,d.jsx)(n,{badge:`переход`,badgeTone:`str`,title:`API и CLI используют одну SQLite`,children:`Перенесёте прежние задачи и переключите оба интерфейса одним шагом. Затем удалите JSON-backend и проверите, что приложению он больше не нужен.`})]})]}),(0,d.jsxs)(s,{number:`04`,title:`Неделя 4 · Проверьте надёжность и подготовьте Planner к передаче`,children:[(0,d.jsx)(o,{children:`Теперь Planner уже работает на SQLite. Рекомендую начать с поведения при ошибках, затем посмотреть на SQL реальных сценариев и пройти проект целиком. Если запрос можно улучшить, сначала найдите подтверждение лишней работы, затем проверьте изменение.`}),(0,d.jsx)(c,{variant:`connected`,items:[{title:`76 · Сбой БД: API и CLI`,description:`Отделите недоступность хранения от неверного ввода, отсутствующей задачи и внутренней ошибки. Верните понятный отказ API и CLI без ложного успеха.`},{title:`76.1 · Rollback и повтор`,description:`Проверьте реальный отказ до commit, rollback и следующую независимую операцию. Убедитесь, что уже подтверждённая запись не объявляется отменённой.`},{title:`77 · SQL-запросы Planner`,description:`Проследите запросы для списка, одной задачи, статистики и поиска. Свяжите SQL с действием Planner, не раскрывая данные пользователей в логах.`},{title:`78 · Улучшаем SQL-запрос`,description:`Найдите лишнюю работу по наблюдениям и исправьте один участок либо защитите уже достаточный запрос проверкой. Сравните поведение без обещаний ускорения на глаз.`},{title:`79 · Сквозная проверка`,description:`Пройдите связанную историю API и CLI на одной базе: обычные действия, отказ, повторный запуск и сохранность данных.`},{title:`80 · Передача DB Planner`,description:`Подготовьте чистую копию, настройки и README, затем запустите API и CLI по инструкции. Проверьте тесты и обозначьте, какие темы будут следующими.`}]}),(0,d.jsxs)(r,{children:[(0,d.jsx)(n,{badge:`ошибки`,title:`Отказы понятны и безопасны`,children:`Различите недоступную базу, неверный ввод и внутренний сбой. API вернёт подходящий статус, CLI покажет понятное сообщение, а данные не будут подменены успехом.`}),(0,d.jsx)(n,{badge:`наблюдение`,badgeTone:`float`,title:`Изменения опираются на доказательства`,children:`Увидите SQL за действиями Planner и проверите восстановление после отказа. Исправите только подтверждённую лишнюю работу или докажете, что запрос уже достаточен.`}),(0,d.jsx)(n,{badge:`результат`,badgeTone:`str`,title:`Проект запускается из чистой копии`,children:`Пройдёте API и CLI после нового запуска по README. Сможете показать, как запрос превращается в SQL и результат, и объяснить границы следующего этапа.`})]})]})]})}export{f as LearningRoadmap};